HERO_STR_STATIC(hero_str_2edf4002, "escape the backslash: `\\\\");
HERO_STR_STATIC(hero_str_3e14443c, "a carriage return written as itself inside ");
HERO_STR_STATIC(hero_str_2136798d, " \342\200\224 it is invisible on screen, so the next reader deletes it by retyping the line");
HERO_STR_STATIC(hero_str_5862de0b, "write it as `\\r`");
HERO_STR_STATIC(hero_str_7074e7b6, "this string never closes \342\200\224 strings are single-line, `\"` to `\"`");
HERO_STR_STATIC(hero_str_7caee94f, "char_literal");
